                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    register_email: result['邮箱'],
                    password: result['密码']
                })
            })
            try {
                let data = JSON.parse(java.ajax(`${base_url}/login_api,${options}`))
                if (data.code == 0) {
                    //java.toast(deviceId)
